219	        HttpHeaders headers = new HttpHeaders();
220	        Visit visit = visitMapper.toVisit(visitFieldsDto);
221	        Pet pet = new Pet();
222	        pet.setId(petId);
223	        visit.setPet(pet);
224	        this.clinicService.saveVisit(visit);
225	        VisitDto visitDto = visitMapper.toVisitDto(visit);
226	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
227	            .buildAndExpand(visit.getId()).toUri());
228	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
229	    }
230	
231	
232	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
233	    @Override
234	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
235	        Owner owner = this.clinicService.findOwnerById(ownerId);
236	        if (owner != null) {
237	            Pet pet = owner.getPet(petId);
238	            if (pet != null) {
239	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
240	            }
241	        }
242	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
243	    }
244	
245	    /**
246	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
247	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
248	     *
249	     * @param fields the submitted owner fields
250	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
251	     *                                        {@code null} or blank, or if address is blank after
252	     *                                        normalization
253	     */
254	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
255	        List<String> missing = new ArrayList<>();
256	        if (isBlank(fields.getFirstName())) {
257	            missing.add("firstName");
258	        }
259	        if (isBlank(fields.getLastName())) {
260	            missing.add("lastName");
261	        }
262	        if (isBlank(normalizeAddress(fields.getAddress()))) {
263	            missing.add("address");
264	        }
265	        if (isBlank(fields.getCity())) {
266	            missing.add("city");
267	        }
268	        if (isBlank(fields.getTelephone())) {
269	            missing.add("telephone");
270	        }
271	        if (!missing.isEmpty()) {
272	            throw new RequiredFieldsMissingException(missing);
273	        }
274	    }
275	
276	    private boolean isBlank(String value) {
277	        return value == null || value.isBlank();
278	    }
279	
280	    /**
281	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
282	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
283	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
284	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
285	     *
286	     * @param telephone the raw telephone value from the request
287	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
288	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
289	     */
290	    private String normalizeTelephone(String telephone) {
291	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
292	        String digits;
293	        if (cleaned.startsWith("+")) {
294	            digits = cleaned.substring(1);
295	        } else {
296	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
297	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
298	            digits = "61" + national;
299	        }
300	        if (!digits.matches("[0-9]{8,15}")) {
301	            throw new InvalidTelephoneException(cleaned);
302	        }
303	        return "+" + digits;
304	    }
305	
306	    /**
307	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
308	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
309	     * lower-cased.
310	     *
311	     * @param email the raw email value from the request, or {@code null} if omitted
312	     * @return the lower-cased email, or {@code null} if none was supplied
313	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
314	     */
315	    private String normalizeEmail(String email) {
316	        if (email == null) {
317	            return null;
318	        }
319	        String trimmed = email.strip();
320	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
321	            throw new InvalidEmailException(email);
322	        }
323	        return trimmed.toLowerCase(Locale.ROOT);
324	    }
325	
326	    /**
327	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
328	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
329	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
330	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
331	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
332	     *
333	     * @param address the raw address value from the request (may be {@code null})
334	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
335	     */
336	    private String normalizeAddress(String address) {
337	        if (address == null) {
338	            return "";
339	        }
340	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
341	        if (collapsed.isEmpty()) {
342	            return "";
343	        }
344	        String[] tokens = collapsed.split(" ");
345	        StringBuilder sb = new StringBuilder(collapsed.length());
346	        for (int i = 0; i < tokens.length; i++) {
347	            if (i > 0) {
348	                sb.append(' ');
349	            }
350	            sb.append(expandAddressAbbreviation(tokens[i]));
351	        }
352	        return sb.toString();
353	    }
354	
355	    /**
356	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
357	     * returns the token unchanged when it is not a recognised abbreviation.
358	     *
359	     * @param token an upper-cased whole-word address token
360	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
361	     */
362	    private String expandAddressAbbreviation(String token) {
363	        return switch (token) {
364	            case "ST" -> "STREET";
365	            case "RD" -> "ROAD";
366	            case "AVE" -> "AVENUE";
367	            default -> token;
368	        };
369	    }
370	
371	    /**
372	     * Rejects a create request whose normalized telephone is already used by another owner. Owners store
373	     * their telephone in normalized E.164 form, so an exact string comparison of E.164 values is sufficient.
374	     *
375	     * @param telephone the normalized (E.164) telephone of the owner being created
376	     * @throws DuplicateTelephoneException if any existing owner already uses the telephone
377	     */
378	    /**
379	     * Builds the customer code assigned to a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
380	     * where {@code CITY3} is the upper-cased first three letters of the owner's city, {@code LAST3} the
381	     * upper-cased first three letters of the owner's last name, and {@code NNNN} a per-city 4-digit
382	     * zero-padded sequence equal to one more than the number of owners already in that city (e.g.
383	     * {@code 'SYD-SMI-0007'}). The code is computed before the new owner is persisted, so the count excludes
384	     * it. Cities are matched case-insensitively so that owners sharing a {@code CITY3} prefix share a sequence.
385	     *
386	     * @param city the owner's city
387	     * @param lastName the owner's last name
388	     * @return the assigned customer code
389	     */
390	    private String generateCustomerCode(String city, String lastName) {
391	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
392	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
393	        int sequence = (int) this.clinicService.findAllOwners().stream()
394	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
395	            .count() + 1;
396	        return String.format("%s-%s-%04d", city3, last3, sequence);
397	    }
398	
399	    /**
400	     * Counts how many existing owners already share the given first name and last name, compared
401	     * case-insensitively. The count is taken before the new owner is persisted, so it excludes the
402	     * owner being created.
403	     *
404	     * @param firstName the first name of the owner being created
405	     * @param lastName the last name of the owner being created
406	     * @return the number of existing owners with the same first and last name (case-insensitively)
407	     */
408	    private int countNamesakes(String firstName, String lastName) {
409	        return (int) this.clinicService.findAllOwners().stream()
410	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
411	                && lastName.equalsIgnoreCase(existing.getLastName()))
412	            .count();
413	    }
414	
415	    /**
416	     * The maximum number of owners permitted in a single city. A create request whose city already
417	     * holds this many owners is rejected.
418	     */
419	    private static final int CITY_OWNER_LIMIT = 50;
420	
421	    /**
422	     * Rejects a create request whose city already contains {@link #CITY_OWNER_LIMIT} or more owners.
423	     * Cities are matched case-insensitively, mirroring the per-city customer-code sequence, so owners
424	     * differing only in the casing of their city share one capacity pool. The count is taken before the
425	     * new owner is persisted, so it excludes the owner being created.
426	     *
427	     * @param city the city of the owner being created
428	     * @throws CityOwnerLimitExceededException if the city already holds the maximum number of owners
429	     */
430	    private void rejectCityAtCapacity(String city) {
431	        long existing = this.clinicService.findAllOwners().stream()
432	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
433	            .count();
434	        if (existing >= CITY_OWNER_LIMIT) {
435	            throw new CityOwnerLimitExceededException(city, CITY_OWNER_LIMIT);
436	        }
437	    }
438	
439	    /**
440	     * The maximum number of owners permitted to be created in a single day. A create request whose
441	     * registration date already holds this many owners is rejected.
442	     */
443	    private static final int DAILY_OWNER_LIMIT = 100;
444	
445	    /**
446	     * Rejects a create request when {@link #DAILY_OWNER_LIMIT} or more owners have already been created
447	     * on the same day, compared by {@code registrationDate}. The count is taken before the new owner is
448	     * persisted, so it excludes the owner being created.
449	     *
450	     * @param registrationDate the registration date of the owner being created
451	     * @throws DailyOwnerLimitExceededException if the day already holds the maximum number of owners
452	     */
453	    /**
454	     * Adjusts an effective registration date so that it always falls on a business day. When the given
455	     * date is a Saturday or Sunday it is rolled forward to the following Monday; a weekday is returned
456	     * unchanged. This applies equally to a date supplied in the request and to a date defaulted to the
457	     * server date, and the adjusted value is what becomes the owner's {@code registrationDate}, so every
458	     * value derived from it (the membership number's year segment, the daily create-limit count) uses the
459	     * business-day-adjusted date.
460	     *
461	     * @param date the effective registration date, supplied or defaulted
462	     * @return the same date when it is a weekday, otherwise the next Monday
463	     */
464	    private LocalDate rollToBusinessDay(LocalDate date) {
465	        DayOfWeek day = date.getDayOfWeek();
466	        if (day == DayOfWeek.SATURDAY) {
467	            return date.plusDays(2);
468	        }
469	        if (day == DayOfWeek.SUNDAY) {
470	            return date.plusDays(1);
471	        }
472	        return date;
473	    }
474	
475	    private void rejectDailyLimitReached(LocalDate registrationDate) {
476	        long existing = this.clinicService.findAllOwners().stream()
477	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
478	            .count();
479	        if (existing >= DAILY_OWNER_LIMIT) {
480	            throw new DailyOwnerLimitExceededException(registrationDate, DAILY_OWNER_LIMIT);
481	        }
482	    }
483	
484	    private void rejectDuplicateTelephone(String telephone) {
485	        boolean taken = this.clinicService.findAllOwners().stream()
486	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
487	        if (taken) {
488	            throw new DuplicateTelephoneException(telephone);
489	        }
490	    }
491	
492	    /**
493	     * Rejects a create request whose owner shares both last name and address with an existing owner.
494	     * Last name and address are compared case-insensitively with runs of whitespace collapsed to a
495	     * single space and leading/trailing whitespace removed, so cosmetic differences (extra spaces,
496	     * differing case) still count as the same household.
497	     *
498	     * @param lastName the last name of the owner being created
499	     * @param address the address of the owner being created
500	     * @throws DuplicateHouseholdException if an existing owner has the same last name and address
501	     */
502	    private void rejectDuplicateHousehold(String lastName, String address) {
503	        String normalizedLastName = normalizeForComparison(lastName);
504	        String normalizedAddress = normalizeForComparison(address);
505	        boolean taken = this.clinicService.findAllOwners().stream()
506	            .anyMatch(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
507	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())));
508	        if (taken) {
509	            throw new DuplicateHouseholdException(lastName, address);
510	        }
511	    }
512	
513	    /**
514	     * Assigns the owner being created into a shared household. When at least one existing owner has the
515	     * same last name and address (compared with {@link #normalizeForComparison}), the joining owner and
516	     * those existing owners are all given the same stable {@code householdId}. An existing member's id is
517	     * reused when present; otherwise a deterministic id derived from the household's last name and address
518	     * is minted, so independently created members of the same household converge on one value. When no
519	     * existing owner shares the household, no id is assigned (the owner simply founds a new address).
520	     *
521	     * @param owner the owner being created, already opted in via {@code sharesHousehold}
522	     */
523	    private void assignHousehold(Owner owner) {
524	        String normalizedLastName = normalizeForComparison(owner.getLastName());
525	        String normalizedAddress = normalizeForComparison(owner.getAddress());
526	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
527	            .filter(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
528	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())))
529	            .toList();
530	        if (housemates.isEmpty()) {
531	            return;
532	        }
533	        String householdId = housemates.stream()
534	            .map(Owner::getHouseholdId)
535	            .filter(id -> id != null && !id.isBlank())
536	            .findFirst()
537	            .orElseGet(() -> householdIdFor(normalizedLastName, normalizedAddress));
538	        owner.setHouseholdId(householdId);
539	        for (Owner housemate : housemates) {
540	            if (!householdId.equals(housemate.getHouseholdId())) {
541	                housemate.setHouseholdId(householdId);
542	                this.clinicService.saveOwner(housemate);
543	            }
544	        }
545	    }
546	
547	    /**
548	     * Derives a stable household identifier from the normalized last name and address of a household, as
549	     * the first 16 hex characters of the SHA-256 digest of {@code '<lastName>|<address>'}. The value is
550	     * deterministic, so any owner independently joining the same household computes the same identifier.
551	     *
552	     * @param normalizedLastName the household's last name, already normalized for comparison
553	     * @param normalizedAddress the household's address, already normalized for comparison
554	     * @return a stable, shareable household identifier
555	     */
556	    private String householdIdFor(String normalizedLastName, String normalizedAddress) {
557	        String key = normalizedLastName + "|" + normalizedAddress;
558	        try {
559	            byte[] digest = MessageDigest.getInstance("SHA-256")
560	                .digest(key.getBytes(StandardCharsets.UTF_8));
561	            StringBuilder sb = new StringBuilder(digest.length * 2);
562	            for (byte b : digest) {
563	                sb.append(String.format("%02x", b));
564	            }
565	            return sb.substring(0, 16);
566	        } catch (NoSuchAlgorithmException e) {
567	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
568	        }
569	    }
570	
571	    /**
572	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
573	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
574	     * lower-cased.
575	     *
576	     * @param value the raw value to normalize (may be {@code null})
577	     * @return the normalized value, or an empty string when {@code value} is {@code null}
578	     */
579	    private String normalizeForComparison(String value) {
580	        if (value == null) {
581	            return "";
582	        }
583	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
584	    }
585	}
